#!/usr/bin/python3
# Update the website on the fdo server from the latest successful "website" CI
# job on the main branch, like gstreamer's ci/gitlab/freedesktop_doc_importer.py
# does for the documentation. Run it from cron.
#
# Does nothing when that job was already deployed. Never uses rsync --delete:
# data/, pkg/, media/, documentation/, ... are not generated by the website.
import os
import gitlab
from datetime import datetime
import tempfile
from subprocess import check_call, call, check_output

BRANCH = "main"
PROJECT = "gstreamer/www"
JOB = "website"
WWW = "/srv/gstreamer.freedesktop.org/www"
HTDOCS = f"{WWW}/htdocs"
# id of the last deployed job, outside of the web root
STAMP = f"{WWW}/.website-job"
EXCLUDES = ["data", "src", "pkg", "media", "documentation", "planet"]

print(f"Running at {datetime.now()}")

gl = gitlab.Gitlab("https://gitlab.freedesktop.org/")
project = gl.projects.get(PROJECT)
job = None
for pipeline in project.pipelines.list(ref=BRANCH, iterator=True):
    jobs = [j for j in pipeline.jobs.list(all=True) if j.name == JOB and j.status == "success"]
    if jobs:
        job = jobs[0]
        break

if job is None:
    print(f"No successful {JOB} job found on {BRANCH}")
    raise SystemExit(1)

try:
    with open(STAMP) as f:
        if f.read().strip() == str(job.id):
            print(f"Job {job.id} already deployed, nothing to do")
            raise SystemExit(0)
except FileNotFoundError:
    pass

with tempfile.TemporaryDirectory() as tmpdir:
    os.chdir(tmpdir)
    url = f"https://gitlab.freedesktop.org/{PROJECT}/-/jobs/{job.id}/artifacts/download"
    print("============================================================================================================================")
    print(f"Updating website from: {url}\n\n")
    check_call(f"wget -q {url} -O www.zip", shell=True)
    print("Unziping file.")
    check_output("unzip -q www.zip", shell=True)
    if not os.path.exists("public/index.html"):
        print("No public/index.html in the artifact, not deploying")
        raise SystemExit(1)
    print("Running rsync.")
    excludes = " ".join(f"--exclude=/{e}" for e in EXCLUDES)
    check_call(f"rsync -rlpt {excludes} public/ {HTDOCS}/", shell=True)
    call(f"chmod -R g+w {HTDOCS}; chgrp -R gstreamer {HTDOCS}", shell=True,
         stderr=open(os.devnull, "w"))

with open(STAMP, "w") as f:
    f.write(f"{job.id}\n")
print(f"Done updating website")
